 {tab==='reports'&&<><div className="toolbar"><input aria-label="Mês dos relatórios" type="month" value={period} onChange={e=>setPeriod(e.target.value)}/><button className="secondary" onClick={()=>window.print()}><Printer size={16}/> Imprimir relatório</button></div><div className="metrics three">{card('Resultado de caixa',currency(income-expenses),'Recebido menos pago',Wallet)}{card('Atendimentos concluídos',completed.length,'Por data agendada no mês',CheckCircle2)}{card('Taxa de não comparecimento',(()=>{const all=s.appointments.filter(a=>dayOf(a.start).startsWith(period)&&['completed','no_show'].includes(a.status));return all.length?(all.filter(a=>a.status==='no_show').length/all.length*100).toFixed(1)+'%':'—'})(),'Faltas ÷ (concluídos + faltas)',Users)}</div><div className="bottom-grid"><section className="panel"><div className="panelhead"><h2>Serviços mais realizados</h2></div>{s.services.map(v=>({v,n:completed.filter(a=>a.serviceIds.includes(v.id)).length})).sort((a,b)=>b.n-a.n).map(({v,n})=><div className="listrow" key={v.id}><span><b>{v.name}</b><small>{v.category}</small></span><b>{n} atendimentos</b></div>)}</section><section className="panel"><div className="panelhead"><h2>Resultado por profissional</h2></div>{s.staff.map(p=>{const ap=completed.filter(a=>a.staffId===p.id);return <div className="listrow" key={p.id}><span><b>{p.name}</b><small>{ap.length} atendimentos concluídos</small></span><b>{currency(ap.reduce((n,a)=>n+amountOf(a),0))}</b></div>})}</section></div><section className="panel spaced"><div className="panelhead"><h2>Leitura dos indicadores</h2></div><div className="pad muted">Receita de serviços considera o valor da comanda após descontos. Sessões de pacote têm valor zero na comanda; a venda entra no caixa uma única vez. O resultado de caixa não equivale ao lucro contábil. Exportações financeiras incluem os lançamentos do mês selecionado.</div></section></>}
 {tab==='settings'&&<div className="settingsgrid"><section className="panel"><div className="panelhead"><div><h2>Identidade do salão</h2><p>Dados usados nas comandas e nos contatos.</p></div></div><form className="pad formgrid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);run({type:'settings',data:Object.fromEntries(f)},false)}}><Field label="Nome do salão" wide><input name="name" required minLength={2} defaultValue={s.settings.name} key={s.settings.name}/></Field><Field label="Telefone"><input name="phone" defaultValue={s.settings.phone}/></Field><Field label="CNPJ / CPF"><input name="taxId" defaultValue={s.settings.taxId}/></Field><Field label="Endereço" wide><input name="address" defaultValue={s.settings.address}/></Field><Field label="Abertura"><input name="open" type="time" required defaultValue={s.settings.open}/></Field><Field label="Fechamento"><input name="close" type="time" required defaultValue={s.settings.close}/></Field><div className="wide"><button className="primary" disabled={busy}><Check size={16}/> Salvar configurações</button></div></form></section><section className="panel"><div className="panelhead"><h2>Acesso e dados</h2></div><div className="pad"><p className="muted">Cada salão possui dados e permissões próprios. O proprietário tem acesso administrativo.</p><button className="secondary full" onClick={()=>open({kind:'member'})}><Plus size={16}/> Adicionar permissão por e-mail</button><p className="footnote muted">Crie a conta em “Contas de acesso” no topo e adicione a permissão neste salão. Não são enviados convites por e-mail.</p>{s.members.map(m=><div className="listrow" key={m.email}><span><b>{m.email}</b><small>{m.role==='reception'?'Recepção':'Financeiro'}</small></span><button className="iconbutton" aria-label="Remover permissão" onClick={()=>open({kind:'removeMember',email:m.email})}><X size={16}/></button></div>)}<hr/><h3>Exportar cópia dos dados</h3><p className="muted">Arquivo JSON completo deste salão. Guarde em local seguro.</p><button className="secondary full" onClick={()=>DownloadFile(`kl-beauty-${today()}.json`,JSON.stringify({format:'kl-beauty-v1',exportedAt:new Date().toISOString(),state:s},null,2))}><Download size={16}/> Exportar dados</button><p className="footnote muted">Nesta versão, a restauração do arquivo requer suporte técnico.</p></div></section><section className="panel wide"><div className="panelhead"><h2>Histórico de alterações</h2><span className="muted">Últimos 30 registros</span></div>{s.audit.slice(0,30).map(a=><div className="listrow" key={a.id}><span><b>{a.action}</b><small>{a.actor}</small></span><small>{new Date(a.at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small></div>)}{!s.audit.length&&<p className="muted pad">As ações salvas ficam registradas aqui.</p>}</section></div>}
